from .enbfsm import EnbFsmInterface
from .wtsfsm import WtsFsmInterface


class ute_fsmaccess(EnbFsmInterface, WtsFsmInterface):

    """Fsm access interface dedicated to establish connection with eNB and Wts

    This library supports multiple setups. Each setup is identified by **alias** argument and establishes own ssh session with Fsm.

    This argument can be specified as follows:
    ::

        Setup Enb Fsm Access      alias=enb1
        Setup WTS Fsm Access      alias=iphy1

    **prompt** arguments are kept for backwards compatibility but starting from v.2.35.0 they have no effect.

    More examples are available in attached Robot Framework example files.


    Keywords
    ********
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def _out_of_scope(self):
        self.teardown_all_aliases_for_enb_fsmaccess()
        self.teardown_all_aliases_for_wts_fsmaccess()
